yle:normal;font-size:9px;color:#8390a2}.hour-strip b{font-size:15px}.hour-strip span{font-size:10px;color:#3c5a75}.week-switch{display:grid;grid-template-columns:repeat(7,1fr);gap:7px}.week-switch button{position:relative;border:1px solid #e2e7ed;background:#fafbfc;border-radius:5px;padding:8px;cursor:pointer}.week-switch button.active{background:#087c66;color:#fff;border-color:#087c66}.week-switch span{display:block;font-size:10px}.week-switch i{position:absolute;right:6px;top:6px;font-style:normal;font-size:9px;background:#e7ecef;color:#546275;border-radius:9px;min-width:17px}.week-switch button.active i{background:#fff;color:#087c66}.agenda-list article{display:grid;grid-template-columns:55px 1fr minmax(100px,160px) auto;align-items:center;gap:12px;padding:9px 4px;border-bottom:1px solid #edf0f3}.agenda-list time{font-weight:700;color:#087c66}.agenda-list span{display:block;font-size:11px;color:#8490a1;margin-top:3px}.expanded .dx-panel{padding:18px}.expanded .mentor-board article{padding:12px 0}.expanded .heat-grid button{height:42px}.expanded .heat-grid button span{width:29px;height:29px}.expanded .hour-strip>div{display:flex;flex-direction:column;padding:9px 5px;gap:5px}@media(max-width:900px){.micro-kpis{grid-template-columns:1fr 1fr}.dashx-grid{grid-template-columns:1fr}.hour-strip,.hour-strip.compact{grid-template-columns:repeat(6,76px)}.weather-now{display:none}.agenda-list article{grid-template-columns:50px 1fr auto}.agenda-list .el-progress{display:none}}@media(max-width:520px){.micro-kpis{grid-template-columns:1fr}.dx-panel{padding:12px}.dash-head-actions{width:100%;justify-content:flex-end}.spotlight{padding:13px}.week-switch{gap:3px}.week-switch button{padding:7px 3px}}
